// Package textutil holds the parts of Python's str every other package
// shares: the character data of CPython's Unicode database (character
// classes, case mappings and names, generated by gen.py and gen_names.py),
// repr(), splitting and stripping, and the int() and float() parsers.
package textutil

import (
	"math/big"
	"strings"

	"github.com/danthedeckie/simpleeval/internal/pyexc"
)

// Basename is posixpath.basename(p): the part of p after its last '/'.
func Basename(p string) string { return p[strings.LastIndexByte(p, '/')+1:] }

// Chr is chr(i) for a code point given as an integer of any size.
func Chr(i *big.Int) (string, error) {
	if !i.IsInt64() || i.Int64() > 1<<31-1 || i.Int64() < -1<<31 {
		return "", pyexc.New("OverflowError", "Python int too large to convert to C int")
	}
	v := i.Int64()
	if v < 0 || v > 0x10FFFF {
		return "", pyexc.New("ValueError", "chr() arg not in range(0x110000)")
	}
	return string(AppendRune(nil, rune(v))), nil
}
